/* «Псс, а ты знаешь?» on the Atlas home page (the tips moved here
   from the program's home page, hub/tips.json). Three tips per topic, worded as facts of a textbook (a short remark may
   follow): [page id, ru, en, zh]; the first tips of all topics come first, then the second ones, then the third ones.
   The tip of the day is chosen by the date (a random start at every launch of the program); «Следующий совет» goes on,
   «Скрыть» hides the card until the program is started again (sessionStorage). The picture is temporary (cut from the
   «spare» pose) until the artist's sprite: ~/Documents/Квил_архив/QuAIL_позы/QuAIL_запросы_v5.md. */
(function(){
const TIPS=[["post", "Соотношение неопределённостей Гейзенберга: Δx·Δp ≥ ħ/2. Чем точнее известно положение частицы, тем шире разброс её импульса — у частицы в ящике это видно прямо на графиках.", "Heisenberg's uncertainty relation: Δx·Δp ≥ ħ/2. The more precisely the position of a particle is known, the wider the spread of its momentum — for a particle in a box it shows right on the plots.", "海森堡不确定关系：Δx·Δp ≥ ħ/2。粒子的位置知道得越精确，其动量的分布就越宽——在箱中粒子的图上可以直接看到。"], ["ham", "Протон тяжелее электрона примерно в 1836 раз. Поэтому ядра движутся намного медленнее электронов, и кинетическую энергию ядер в молекулярном гамильтониане можно сначала отбросить.", "A proton is about 1836 times heavier than an electron. The nuclei therefore move much more slowly than the electrons, and the kinetic energy of the nuclei can first be dropped from the molecular Hamiltonian.", "质子比电子重约 1836 倍。因此原子核的运动比电子慢得多，分子哈密顿量中原子核的动能可以先略去。"], ["bo", "У D₂ та же потенциальная яма, что у H₂, — так следует из приближения Борна–Оппенгеймера, — но нулевые колебания меньше. Поэтому энергия диссоциации D₀ у D₂ больше: 4,56 эВ против 4,48 эВ.", "D₂ has the same potential well as H₂ — this follows from the Born–Oppenheimer approximation — but smaller zero-point vibrations. Its dissociation energy D₀ is therefore larger: 4.56 eV against 4.48 eV.", "D₂ 与 H₂ 的势阱相同——这是玻恩–奥本海默近似的结果——但零点振动更小。因此 D₂ 的解离能 D₀ 更大：4.56 eV 对 4.48 eV。"], ["au", "В атомных единицах ħ = mₑ = e = 4πε₀ = 1. Энергия основного состояния атома водорода равна −1/2 хартри, а 1 хартри = 27,211 эВ = 2625,5 кДж/моль.", "In atomic units ħ = mₑ = e = 4πε₀ = 1. The ground-state energy of the hydrogen atom is −1/2 hartree, and 1 hartree = 27.211 eV = 2625.5 kJ/mol.", "在原子单位中 ħ = mₑ = e = 4πε₀ = 1。氢原子基态能量为 −1/2 哈特里，而 1 哈特里 = 27.211 eV = 2625.5 kJ/mol。"], ["pes", "Переходное состояние — седловая точка первого порядка на поверхности потенциальной энергии: у него ровно одна мнимая частота, и её колебание показывает направление реакции.", "A transition state is a first-order saddle point of the potential energy surface: it has exactly one imaginary frequency, and that vibration shows the direction of the reaction.", "过渡态是势能面上的一阶鞍点：它恰好有一个虚频，该振动指出反应进行的方向。"], ["sym", "Вода относится к точечной группе C2v (4 операции симметрии), аммиак — к C3v (6), метан — к Td (24), бензол — к D6h (24).", "Water belongs to the point group C2v (4 symmetry operations), ammonia to C3v (6), methane to Td (24) and benzene to D6h (24).", "水属于 C2v 点群（4 个对称操作），氨属于 C3v（6 个），甲烷属于 Td（24 个），苯属于 D6h（24 个）。"], ["pauli", "Волновая функция электронов меняет знак при перестановке любых двух электронов. Отсюда принцип Паули: на одной спин-орбитали может находиться не больше одного электрона.", "The wavefunction of electrons changes sign when any two electrons are exchanged. The Pauli principle follows: one spin orbital holds at most one electron.", "交换任意两个电子时，电子波函数改变符号。由此得到泡利原理：一个自旋轨道最多容纳一个电子。"], ["sc", "Матричный элемент гамильтониана между определителями, которые различаются больше чем двумя спин-орбиталями, равен нулю: в гамильтониане нет операторов, действующих сразу на три электрона.", "The Hamiltonian matrix element between determinants that differ in more than two spin orbitals is zero: the Hamiltonian has no operators acting on three electrons at once.", "相差超过两个自旋轨道的行列式之间的哈密顿矩阵元为零：哈密顿量中没有同时作用于三个电子的算符。"], ["scf", "Итерации SCF сходятся не всегда: на каждом шаге орбитали строятся по плотности предыдущего шага. Ускорение DIIS (Пулаи) собирает новую матрицу Фока из нескольких прежних и обычно сокращает число итераций в разы.", "SCF iterations do not always converge: at every step the orbitals are built from the density of the previous one. Pulay's DIIS builds the new Fock matrix from several earlier ones and usually cuts the number of iterations several times.", "SCF 迭代并不总是收敛：每一步的轨道都由上一步的密度构造。Pulay 的 DIIS 加速用之前的几个 Fock 矩阵组合出新的矩阵，通常能把迭代次数减少数倍。"], ["basis", "У воды в базисе STO-3G всего 7 базисных функций, а в 6-31G* — уже 19 (с декартовыми d-функциями). Время расчёта растёт с числом функций ещё быстрее.", "Water has only 7 basis functions in STO-3G and 19 in 6-31G* (with Cartesian d functions). The computing time grows even faster than the number of functions.", "水在 STO-3G 基组中只有 7 个基函数，在 6-31G* 中已有 19 个（笛卡尔 d 函数）。计算时间增长得比基函数数目还快。"], ["nm", "У нелинейной молекулы из N атомов 3N − 6 нормальных колебаний, у линейной — 3N − 5. У CO₂ их четыре; симметричное валентное колебание не меняет дипольного момента и в ИК-спектре не проявляется.", "A nonlinear molecule of N atoms has 3N − 6 normal modes, a linear one 3N − 5. CO₂ has four; its symmetric stretch does not change the dipole moment and does not appear in the IR spectrum.", "由 N 个原子组成的非线性分子有 3N − 6 个简正振动，线性分子有 3N − 5 个。CO₂ 有四个；其对称伸缩振动不改变偶极矩，因此不出现在红外光谱中。"], ["mo", "Кислород O₂ парамагнитен: на двух вырожденных разрыхляющих π*-орбиталях находится по одному электрону с параллельными спинами, основное состояние — триплет ³Σg⁻.", "Oxygen O₂ is paramagnetic: each of the two degenerate antibonding π* orbitals holds one electron with parallel spins, and the ground state is the triplet ³Σg⁻.", "氧气 O₂ 是顺磁性的：两个简并的反键 π* 轨道上各有一个自旋平行的电子，基态为三重态 ³Σg⁻。"], ["terms", "Основной терм атома углерода (2p²) — ³P₀. По правилам Хунда сначала выбирают наибольший спин, затем наибольший орбитальный момент, а у оболочки, заполненной меньше чем наполовину, — наименьшее J.", "The ground term of the carbon atom (2p²) is ³P₀. Hund's rules take the largest spin first, then the largest orbital momentum, and for a shell less than half full the smallest J.", "碳原子（2p²）的基态光谱项是 ³P₀。按照洪特规则，先取最大自旋，再取最大轨道角动量；对于未半满的壳层，取最小的 J。"], ["hat", "Линия Hα серии Бальмера (переход n = 3 → 2) лежит около 656 нм — это красный свет. Все видимые линии водорода — переходы на уровень n = 2.", "The Hα line of the Balmer series (the transition n = 3 → 2) lies near 656 nm — red light. All visible lines of hydrogen are transitions to the level n = 2.", "巴耳末系的 Hα 谱线（n = 3 → 2 跃迁）位于约 656 nm，是红光。氢原子的所有可见谱线都是向 n = 2 能级的跃迁。"], ["var", "Вариационный принцип: энергия любой пробной функции не ниже точной энергии основного состояния. Одна гауссова функция даёт для атома водорода −0,424 хартри вместо −0,5.", "The variational principle: the energy of any trial function is not below the exact ground-state energy. A single Gaussian gives −0.424 hartree for the hydrogen atom instead of −0.5.", "变分原理：任何试探函数的能量都不低于精确的基态能量。单个高斯函数给出的氢原子能量是 −0.424 哈特里，而不是 −0.5。"], ["cf", "В тетраэдрическом поле расщепление d-уровней составляет около 4/9 от октаэдрического при тех же лигандах, поэтому тетраэдрические комплексы почти всегда высокоспиновые.", "In a tetrahedral field the splitting of the d levels is about 4/9 of the octahedral one for the same ligands, so tetrahedral complexes are almost always high-spin.", "在相同配体下，四面体场中 d 能级的分裂约为八面体场的 4/9，因此四面体配合物几乎总是高自旋的。"], ["h2", "Ограниченный метод Хартри–Фока не описывает диссоциацию H₂: на больших расстояниях его функция наполовину ионная (H⁺H⁻), и энергия уходит выше энергии двух атомов водорода.", "Restricted Hartree–Fock cannot describe the dissociation of H₂: at large distances its function is half ionic (H⁺H⁻), and the energy rises above that of two hydrogen atoms.", "限制性哈特里–福克方法无法描述 H₂ 的解离：在大距离处其波函数有一半是离子性的（H⁺H⁻），能量高于两个氢原子的能量。"], ["he", "Функция гелия с эффективным зарядом ζ = 27/16 даёт −2,8477 хартри при точной энергии −2,9037. Заряд меньше 2, потому что каждый электрон частично экранирует ядро для другого.", "A helium function with the effective charge ζ = 27/16 gives −2.8477 hartree against the exact −2.9037. The charge is below 2 because each electron partly screens the nucleus from the other.", "有效电荷 ζ = 27/16 的氦原子波函数给出 −2.8477 哈特里，而精确能量为 −2.9037。电荷小于 2，是因为每个电子都对另一个电子部分屏蔽了原子核。"], ["dens", "Электронная плотность — наблюдаемая величина: её измеряют рентгеновской дифракцией. По теореме Хоэнберга–Кона плотность основного состояния однозначно определяет гамильтониан.", "The electron density is an observable: it is measured by X-ray diffraction. By the Hohenberg–Kohn theorem the ground-state density determines the Hamiltonian uniquely.", "电子密度是可观测量：可以用 X 射线衍射测量。根据霍恩伯格–科恩定理，基态密度唯一地确定哈密顿量。"], ["opt", "Наискорейший спуск с большим шагом расходится, а метод Ньютона вблизи минимума сходится квадратично — обычно ему хватает нескольких шагов.", "Steepest descent with a large step diverges, while Newton's method converges quadratically near a minimum — usually a few steps are enough.", "步长过大的最速下降法会发散，而牛顿法在极小值附近二次收敛——通常几步就够了。"], ["thermo", "Энтропия молекулы газа почти целиком поступательная и вращательная: у воды при 298 K колебания дают меньше 0,1 Дж/(моль·К).", "The entropy of a gas molecule is almost entirely translational and rotational: for water at 298 K the vibrations give less than 0.1 J/(mol·K).", "气体分子的熵几乎全部来自平动和转动：298 K 时水的振动贡献不到 0.1 J/(mol·K)。"], ["eqm", "Константа равновесия связана со стандартной энергией Гиббса: K = exp(−ΔG°/RT). При 298 K изменение ΔG° на 5,7 кДж/моль меняет K в 10 раз.", "The equilibrium constant is tied to the standard Gibbs energy: K = exp(−ΔG°/RT). At 298 K a change of ΔG° by 5.7 kJ/mol changes K tenfold.", "平衡常数与标准吉布斯自由能相关：K = exp(−ΔG°/RT)。在 298 K，ΔG° 改变 5.7 kJ/mol，K 就改变 10 倍。"], ["kin", "По теории переходного состояния (Эйринг) k = (k_BT/h)·exp(−ΔG‡/RT). При комнатной температуре каждые 5,7 кДж/моль барьера замедляют реакцию в 10 раз.", "In transition state theory (Eyring) k = (k_BT/h)·exp(−ΔG‡/RT). At room temperature every 5.7 kJ/mol of barrier slows a reaction tenfold.", "按照过渡态理论（艾林），k = (k_BT/h)·exp(−ΔG‡/RT)。在室温下，势垒每增加 5.7 kJ/mol，反应就慢 10 倍。"], ["cicc", "Полное КВ точно в данном базисе, но число определителей растёт факториально: для воды даже в небольшом базисе это уже миллионы.", "Full CI is exact within a basis set, but the number of determinants grows factorially: for water it is millions even in a small basis.", "完全组态相互作用在给定基组内是精确的，但行列式数目按阶乘增长：即使在小基组中，水分子也已有数百万个。"], ["mp2", "MP2 — второй порядок теории возмущений Мёллера–Плессе — обычно даёт 80–90 % энергии корреляции около равновесия, а его стоимость растёт как N⁵.", "MP2, the second order of Møller–Plesset perturbation theory, usually gives 80–90 % of the correlation energy near equilibrium, and its cost grows as N⁵.", "MP2，即 Møller–Plesset 微扰理论的二阶，通常在平衡结构附近给出 80–90% 的相关能，其计算量按 N⁵ 增长。"], ["cas", "При растяжении тройной связи N₂ одной конфигурации мало: в CASSCF заселённости натуральных орбиталей отходят от 2 и 0 и при диссоциации стремятся к 1.", "When the triple bond of N₂ is stretched, one configuration is not enough: in CASSCF the natural orbital occupations move away from 2 and 0 and approach 1 at dissociation.", "拉伸 N₂ 的三键时，一个组态已不够：在 CASSCF 中，自然轨道占据数偏离 2 和 0，并在解离时趋近于 1。"], ["solv", "Энергия сольватации иона по Борну пропорциональна z²/r·(1 − 1/ε): у маленького Li⁺ она намного больше, чем у Cs⁺.", "The Born solvation energy of an ion is proportional to z²/r·(1 − 1/ε): for the small Li⁺ it is much larger than for Cs⁺.", "按玻恩模型，离子的溶剂化能正比于 z²/r·(1 − 1/ε)：小离子 Li⁺ 的溶剂化能比 Cs⁺ 大得多。"], ["lad", "Лестница Якова (Пердью): LDA → GGA → мета-GGA → гибриды → двойные гибриды. Каждая ступень добавляет новое: градиент плотности, кинетическую плотность, точный обмен, виртуальные орбитали.", "Jacob's ladder (Perdew): LDA → GGA → meta-GGA → hybrids → double hybrids. Each rung adds something: the density gradient, the kinetic energy density, exact exchange, virtual orbitals.", "雅各布天梯（Perdew）：LDA → GGA → meta-GGA → 杂化 → 双杂化。每一级都加入新的信息：密度梯度、动能密度、精确交换、虚轨道。"], ["cbs", "Энергия корреляции сходится по кардинальному числу базиса X как X⁻³, поэтому по двум базисам (например, cc-pVTZ и cc-pVQZ) можно оценить предел полного базиса.", "The correlation energy converges with the cardinal number X of the basis as X⁻³, so two basis sets (cc-pVTZ and cc-pVQZ, say) give an estimate of the complete basis set limit.", "相关能随基组基数 X 按 X⁻³ 收敛，因此用两个基组（例如 cc-pVTZ 和 cc-pVQZ）就能估计完全基组极限。"], ["bsse", "В малом базисе димер кажется связанным сильнее, чем на самом деле: каждая молекула «одалживает» функции соседки. Поправка противовеса Бойса–Бернарди считает мономеры в полном базисе димера.", "In a small basis a dimer looks more strongly bound than it is: each molecule “borrows” the functions of its neighbour. The Boys–Bernardi counterpoise correction computes the monomers in the full basis of the dimer.", "在小基组中，二聚体看起来比实际结合得更紧：每个分子都“借用”了邻居的基函数。Boys–Bernardi 平衡校正在二聚体的完整基组中计算单体。"], ["chg", "Атомный заряд — не наблюдаемая величина: у разных схем (Малликен, Лёвдин, NPA, Бейдер) значения различаются, иногда даже знаком.", "An atomic charge is not an observable: different schemes (Mulliken, Löwdin, NPA, Bader) give different values, sometimes even of opposite sign.", "原子电荷不是可观测量：不同方案（Mulliken、Löwdin、NPA、Bader）给出的值不同，有时连符号都不同。"], ["exc", "Флуоресценция всегда краснее поглощения — это стоксов сдвиг: после возбуждения молекула успевает перестроить геометрию, прежде чем излучить.", "Fluorescence is always redder than absorption — the Stokes shift: after excitation the molecule has time to rearrange its geometry before it emits.", "荧光总是比吸收更红——这就是斯托克斯位移：激发后分子在发光之前已经改变了几何构型。"], ["val", "RHF/STO-3G для воды в стандартной учебной геометрии даёт −74,963 хартри — классический эталон, по которому сверяют программы.", "RHF/STO-3G for water at the standard textbook geometry gives −74.963 hartree — a classic reference used to check programs.", "在标准教科书几何下，水的 RHF/STO-3G 能量为 −74.963 哈特里——这是用来核对程序的经典基准。"], ["disp", "Атомы гелия притягиваются только благодаря дисперсии: метод Хартри–Фока даёт для He₂ чистое отталкивание.", "Helium atoms attract each other only through dispersion: Hartree–Fock gives pure repulsion for He₂.", "氦原子之间只靠色散力相互吸引：哈特里–福克方法对 He₂ 只给出排斥。"], ["aim", "По Бейдеру молекула делится на атомные бассейны поверхностями нулевого потока градиента плотности; заряд атома — интеграл плотности по его бассейну.", "In Bader's theory a molecule is divided into atomic basins by surfaces of zero flux of the density gradient; the charge of an atom is the integral of the density over its basin.", "在 Bader 理论中，分子被密度梯度零通量面划分为原子盆；原子的电荷是密度在其原子盆上的积分。"], ["dft", "Ошибка самодействия: в приближении локальной плотности единственный электрон атома водорода отталкивает сам себя, и энергия выходит выше −0,5 хартри — около −0,479.", "The self-interaction error: in the local density approximation the single electron of the hydrogen atom repels itself, and the energy comes out above −0.5 hartree — about −0.479.", "自相互作用误差：在局域密度近似中，氢原子唯一的电子会排斥它自己，能量高于 −0.5 哈特里——约为 −0.479。"], ["huckel", "По Хюккелю энергия делокализации бензола равна 2β, а у циклобутадиена — нулю. Отсюда правило ароматичности 4n + 2.", "In Hückel theory the delocalization energy of benzene is 2β, and that of cyclobutadiene is zero. The 4n + 2 aromaticity rule follows from this.", "按休克尔理论，苯的离域能为 2β，而环丁二烯的离域能为零。由此得到 4n + 2 芳香性规则。"], ["wh", "Термическая электроциклизация бутадиена идёт конротаторно, а фотохимическая — дисротаторно: всё решает симметрия ВЗМО основного и возбуждённого состояний.", "The thermal electrocyclization of butadiene is conrotatory and the photochemical one disrotatory: the symmetry of the HOMO of the ground and the excited state decides.", "丁二烯的热电环化为顺旋，光化学电环化为对旋：决定因素是基态与激发态 HOMO 的对称性。"], ["nmr", "Прибор «на 600 МГц» назван по частоте протонов: его поле — 14,1 тесла, в сотни тысяч раз сильнее земного.", "A “600 MHz” spectrometer is named after the proton frequency: its field is 14.1 tesla, hundreds of thousands of times the Earth’s.", "“600 MHz”谱仪以质子频率命名：其磁场为 14.1 特斯拉，是地磁场的数十万倍。"], ["conf", "Барьер вращения в этане — 12 кДж/моль: при комнатной температуре метильные группы поворачиваются миллиарды раз в секунду.", "The rotation barrier of ethane is 12 kJ/mol: at room temperature the methyl groups turn billions of times per second.", "乙烷的旋转能垒为 12 kJ/mol：室温下甲基每秒转动数十亿次。"], ["rel", "Цвет золота — релятивистский эффект: сжатие 6s и расширение 5d сокращают зазор между ними, и золото поглощает синий свет.", "The colour of gold is a relativistic effect: the contraction of 6s and the expansion of 5d narrow the gap between them, and gold absorbs blue light.", "金的颜色是一种相对论效应：6s 收缩、5d 膨胀使两者间隙变小，金因而吸收蓝光。"], ["cryst", "Плотность кристалла считают по шести параметрам ячейки и её содержимому: ρ = Z·M/(N_A·V) — так проверяют расшифрованную структуру.", "The density of a crystal follows from the six cell parameters and the contents: ρ = Z·M/(N_A·V) — this is how a solved structure is checked.", "晶体密度由六个晶胞参数和晶胞内容求出：ρ = Z·M/(N_A·V)——解析出的结构就这样检验。"], ["walsh", "BeH₂ линейна, а H₂O изогнута по одной причине: при изгибе сильно стабилизируется орбиталь 2a₁, и она занята только начиная с пяти валентных электронов.", "BeH₂ is linear and H₂O bent for one reason: on bending the 2a₁ orbital is strongly stabilised, and it is occupied only from five valence electrons on.", "BeH₂ 为直线形而 H₂O 为弯曲形，原因相同：弯曲时 2a₁ 轨道被大幅稳定，而它从第五个价电子起才被占据。"], ["post", "При измерении система переходит в собственное состояние измеряемой величины, а вероятность получить значение aₙ равна |cₙ|² — квадрату коэффициента разложения волновой функции.", "A measurement leaves the system in an eigenstate of the measured quantity, and the probability of the value aₙ is |cₙ|² — the square of the expansion coefficient of the wavefunction.", "测量使体系处于被测量的本征态，得到 aₙ 的概率等于 |cₙ|²——波函数展开系数的平方。"], ["ham", "Молекулярный гамильтониан без релятивистских поправок состоит из пяти слагаемых: кинетических энергий ядер и электронов, притяжения электронов к ядрам, отталкивания электронов и отталкивания ядер.", "Without relativistic corrections the molecular Hamiltonian has five terms: the kinetic energies of the nuclei and of the electrons, the electron–nucleus attraction, the electron repulsion and the nuclear repulsion.", "不含相对论修正的分子哈密顿量由五项组成：原子核与电子的动能、电子与核的吸引、电子之间的排斥以及核之间的排斥。"], ["bo", "В гармоническом приближении частота колебания ω = √(k/μ). При замене H на D частота связи уменьшается почти в √2 раз: у C–H около 3000 см⁻¹, у C–D около 2200 см⁻¹.", "In the harmonic approximation the vibrational frequency is ω = √(k/μ). Replacing H by D lowers the bond frequency by almost √2: C–H is near 3000 cm⁻¹, C–D near 2200 cm⁻¹.", "在谐振近似中振动频率 ω = √(k/μ)。把 H 换成 D 后，键的频率几乎降低 √2 倍：C–H 约 3000 cm⁻¹，C–D 约 2200 cm⁻¹。"], ["au", "Единица длины в атомных единицах — боровский радиус a₀ = 0,529177 Å. Это наиболее вероятное расстояние от электрона до ядра в основном состоянии атома водорода.", "The unit of length in atomic units is the Bohr radius a₀ = 0.529177 Å. It is the most probable electron–nucleus distance in the ground state of the hydrogen atom.", "原子单位中的长度单位是玻尔半径 a₀ = 0.529177 Å。它是氢原子基态中电子与核之间最可能的距离。"], ["pes", "Минимумы поверхности потенциальной энергии — устойчивые структуры, у них все частоты вещественны. Путь наименьшей энергии от седла к минимумам называют внутренней координатой реакции (IRC).", "The minima of the potential energy surface are stable structures with all frequencies real. The path of least energy from the saddle down to the minima is called the intrinsic reaction coordinate (IRC).", "势能面上的极小点是稳定结构，所有频率都是实数。从鞍点通往极小点的最低能量路径称为内禀反应坐标（IRC）。"], ["sym", "Молекула с центром инверсии не может иметь постоянного дипольного момента, поэтому дипольный момент CO₂ и бензола равен нулю.", "A molecule with a centre of inversion cannot have a permanent dipole moment, so the dipole moment of CO₂ and of benzene is zero.", "有对称中心的分子不可能有永久偶极矩，因此 CO₂ 和苯的偶极矩为零。"], ["pauli", "Вокруг каждого электрона есть «дырка Ферми»: электроны с одинаковым спином не встречаются в одной точке пространства, даже если не учитывать их отталкивание.", "Around every electron there is a “Fermi hole”: electrons of the same spin never meet at one point, even when their repulsion is left out.", "每个电子周围都有一个“费米空穴”：即使不考虑排斥，自旋相同的电子也不会出现在空间同一点。"], ["sc", "Теорема Бриллюэна: матричные элементы между хартри-фоковским определителем и однократно возбуждёнными равны нулю. Поэтому первую поправку к энергии дают двукратные возбуждения.", "Brillouin's theorem: the matrix elements between the Hartree–Fock determinant and singly excited ones are zero. The first correction to the energy therefore comes from double excitations.", "布里渊定理：哈特里–福克行列式与单激发行列式之间的矩阵元为零。因此对能量的第一个修正来自双激发。"], ["scf", "Сходимость SCF проверяют по двум признакам: изменению энергии и изменению матрицы плотности между итерациями. Малое изменение энергии ещё не значит, что плотность сошлась.", "SCF convergence is checked by two criteria: the change of the energy and the change of the density matrix between iterations. A small energy change alone does not mean the density has converged.", "SCF 收敛用两个判据检验：迭代之间能量的变化和密度矩阵的变化。仅能量变化小并不意味着密度已经收敛。"], ["basis", "Гауссовы функции удобны тем, что произведение двух гауссианов на разных центрах — снова гауссиан, поэтому интегралы считаются быстро. Правильного излома у ядра (каспа) у них нет.", "Gaussian functions are convenient because the product of two Gaussians on different centres is again a Gaussian, so the integrals are fast. They lack the correct cusp at the nucleus.", "高斯函数方便之处在于：两个不同中心的高斯函数之积仍是高斯函数，因此积分计算很快。但它们在原子核处没有正确的尖点。"], ["nm", "Колебание активно в ИК-спектре, если при нём меняется дипольный момент, и в спектре комбинационного рассеяния — если меняется поляризуемость.", "A vibration is IR active if it changes the dipole moment and Raman active if it changes the polarizability.", "若振动改变偶极矩，它在红外光谱中有活性；若改变极化率，则在拉曼光谱中有活性。"], ["mo", "Порядок связи равен половине разности чисел электронов на связывающих и разрыхляющих орбиталях: у N₂ он равен 3, у O₂ — 2, у F₂ — 1.", "The bond order is half the difference between the numbers of electrons in bonding and antibonding orbitals: 3 for N₂, 2 for O₂, 1 for F₂.", "键级等于成键轨道与反键轨道电子数之差的一半：N₂ 为 3，O₂ 为 2，F₂ 为 1。"], ["terms", "Конфигурация p² даёт три терма — ³P, ¹D и ¹S — и всего 15 микросостояний: 9 + 5 + 1.", "The configuration p² gives three terms — ³P, ¹D and ¹S — and 15 microstates in all: 9 + 5 + 1.", "p² 组态给出三个光谱项——³P、¹D 和 ¹S——共 15 个微观状态：9 + 5 + 1。"], ["hat", "Энергия уровня атома водорода зависит только от главного квантового числа: Eₙ = −1/(2n²) хартри, и уровень n вырожден n² раз (без учёта спина).", "The energy of a hydrogen level depends only on the principal quantum number: Eₙ = −1/(2n²) hartree, and level n is n²-fold degenerate (spin aside).", "氢原子能级只取决于主量子数：Eₙ = −1/(2n²) 哈特里，能级 n 是 n² 重简并的（不计自旋）。"], ["var", "Метод Ритца сводит вариационную задачу к собственной задаче матрицы, и каждое следующее собственное значение — верхняя граница соответствующего возбуждённого уровня (теорема Хиллерааса–Ундхейма–Макдональда).", "The Ritz method turns the variational problem into a matrix eigenvalue problem, and each further eigenvalue is an upper bound to the corresponding excited level (the Hylleraas–Undheim–MacDonald theorem).", "里兹方法把变分问题化为矩阵本征值问题，后续的每个本征值都是相应激发能级的上界（Hylleraas–Undheim–MacDonald 定理）。"], ["cf", "В октаэдре d-орбитали расщепляются на три нижних t₂g и две верхних e_g. Энергия стабилизации кристаллическим полем у низкоспинового d⁶ (t₂g⁶) равна −2,4 Δₒ без учёта энергии спаривания.", "In an octahedron the d orbitals split into three lower t₂g and two upper e_g. The crystal field stabilization energy of low-spin d⁶ (t₂g⁶) is −2.4 Δₒ, pairing energy aside.", "在八面体中，d 轨道分裂为三个较低的 t₂g 和两个较高的 e_g。低自旋 d⁶（t₂g⁶）的晶体场稳定化能为 −2.4 Δₒ（不计成对能）。"], ["h2", "Энергия диссоциации H₂ Dₑ равна 4,75 эВ, а равновесное расстояние — 0,741 Å, или 1,40 бор.", "The dissociation energy of H₂ Dₑ is 4.75 eV and the equilibrium distance 0.741 Å, or 1.40 bohr.", "H₂ 的解离能 Dₑ 为 4.75 eV，平衡键长为 0.741 Å，即 1.40 玻尔。"], ["he", "Энергия Хартри–Фока гелия равна −2,8617 хартри; оставшиеся 0,042 хартри, около 26 ккал/моль, — энергия корреляции.", "The Hartree–Fock energy of helium is −2.8617 hartree; the remaining 0.042 hartree, about 26 kcal/mol, is the correlation energy.", "氦原子的哈特里–福克能量为 −2.8617 哈特里；剩下的 0.042 哈特里（约 26 kcal/mol）就是相关能。"], ["dens", "У ядра плотность имеет излом (касп): её наклон задаётся зарядом ядра, ∂ρ/∂r = −2Zρ при r → 0 (теорема Като).", "At a nucleus the density has a cusp: its slope is set by the nuclear charge, ∂ρ/∂r = −2Zρ as r → 0 (Kato's theorem).", "在原子核处密度有尖点：其斜率由核电荷决定，r → 0 时 ∂ρ/∂r = −2Zρ（加藤定理）。"], ["opt", "Квазиньютоновские методы (BFGS) не считают вторые производные на каждом шаге, а уточняют приближённый гессиан по изменению градиентов.", "Quasi-Newton methods (BFGS) do not compute second derivatives at every step; they update an approximate Hessian from the change of the gradients.", "拟牛顿法（BFGS）不在每一步计算二阶导数，而是根据梯度的变化更新近似的黑塞矩阵。"], ["thermo", "Энергия нулевых колебаний ½Σhνᵢ есть даже при абсолютном нуле; у воды она около 56 кДж/моль (13 ккал/моль).", "The zero-point energy ½Σhνᵢ remains even at absolute zero; for water it is about 56 kJ/mol (13 kcal/mol).", "即使在绝对零度，零点能 ½Σhνᵢ 依然存在；水的零点能约为 56 kJ/mol（13 kcal/mol）。"], ["eqm", "Синтез аммиака N₂ + 3H₂ ⇌ 2NH₃ экзотермичен (ΔH° ≈ −92 кДж/моль) и уменьшает число молей газа, поэтому с ростом температуры константа равновесия убывает.", "The synthesis of ammonia N₂ + 3H₂ ⇌ 2NH₃ is exothermic (ΔH° ≈ −92 kJ/mol) and reduces the number of moles of gas, so its equilibrium constant falls as the temperature rises.", "合成氨 N₂ + 3H₂ ⇌ 2NH₃ 是放热反应（ΔH° ≈ −92 kJ/mol），且气体物质的量减少，因此平衡常数随温度升高而减小。"], ["kin", "Множитель k_BT/h при 298 K равен примерно 6,2·10¹² с⁻¹ — так быстро шла бы реакция совсем без барьера.", "The factor k_BT/h at 298 K is about 6.2·10¹² s⁻¹ — the rate a reaction would have with no barrier at all.", "298 K 时因子 k_BT/h 约为 6.2·10¹² s⁻¹——这是完全没有势垒时反应的速率。"], ["cicc", "Обрезанное КВ (CISD) не размерно-согласовано: энергия двух далёких молекул не равна сумме их энергий. У метода связанных кластеров CCSD этого недостатка нет.", "Truncated CI (CISD) is not size-consistent: the energy of two distant molecules is not the sum of their energies. Coupled cluster CCSD does not have this flaw.", "截断组态相互作用（CISD）不具有大小一致性：两个相距很远的分子的能量不等于各自能量之和。耦合簇方法 CCSD 没有这个缺点。"], ["mp2", "При растяжении связи H₂ поправка MP2, построенная на RHF, неограниченно растёт: знаменатели с энергиями возбуждения стремятся к нулю.", "When the H₂ bond is stretched, the MP2 correction built on RHF grows without bound: the denominators with excitation energies go to zero.", "拉伸 H₂ 键时，基于 RHF 的 MP2 修正会无限增大：含激发能的分母趋于零。"], ["cas", "CASSCF учитывает статическую корреляцию — смешивание близких по энергии конфигураций. Динамическую корреляцию добавляют потом, например методами CASPT2 или NEVPT2.", "CASSCF captures static correlation — the mixing of configurations close in energy. Dynamic correlation is added afterwards, for example by CASPT2 or NEVPT2.", "CASSCF 描述静态相关——能量相近组态的混合。动态相关之后再加入，例如用 CASPT2 或 NEVPT2。"], ["solv", "В континуальных моделях (PCM, CPCM, SMD) растворитель — диэлектрик с проницаемостью ε, а молекула находится в полости из сфер вокруг атомов.", "In continuum models (PCM, CPCM, SMD) the solvent is a dielectric with permittivity ε, and the molecule sits in a cavity made of spheres around the atoms.", "在连续介质模型（PCM、CPCM、SMD）中，溶剂是介电常数为 ε 的电介质，分子位于由原子周围球体构成的空腔中。"], ["lad", "Гибридный функционал B3LYP содержит 20 % точного обмена Хартри–Фока, PBE0 — 25 %.", "The hybrid functional B3LYP contains 20 % of exact Hartree–Fock exchange, PBE0 25 %.", "杂化泛函 B3LYP 含 20% 的精确哈特里–福克交换，PBE0 含 25%。"], ["cbs", "Энергия Хартри–Фока сходится по базису гораздо быстрее энергии корреляции — примерно экспоненциально.", "The Hartree–Fock energy converges with the basis much faster than the correlation energy — roughly exponentially.", "哈特里–福克能量随基组的收敛比相关能快得多——大致呈指数收敛。"], ["bsse", "Суперпозиционная ошибка уменьшается с ростом базиса и исчезает в пределе полного базиса.", "The basis set superposition error shrinks as the basis grows and vanishes in the complete basis set limit.", "基组重叠误差随基组增大而减小，在完全基组极限下消失。"], ["chg", "Заряды по Малликену сильно зависят от базиса и в диффузных базисах ведут себя непредсказуемо; заряды по Бейдеру и NPA устойчивее.", "Mulliken charges depend strongly on the basis and behave erratically in diffuse bases; Bader and NPA charges are more stable.", "Mulliken 电荷强烈依赖于基组，在弥散基组中表现难以预料；Bader 电荷和 NPA 电荷更稳定。"], ["exc", "Правило Каши: излучение почти всегда идёт с нижнего возбуждённого состояния данной мультиплетности, какое бы состояние ни было возбуждено.", "Kasha's rule: emission almost always comes from the lowest excited state of a given multiplicity, whichever state was excited.", "卡沙规则：无论激发到哪个态，发射几乎总是来自给定多重度的最低激发态。"], ["val", "Совпадение с эталоном до 10⁻⁶ хартри проверяет программу, но не метод: близость к эксперименту зависит от метода и базиса.", "Agreement with a reference to 10⁻⁶ hartree checks the program, not the method: closeness to experiment depends on the method and the basis.", "与基准一致到 10⁻⁶ 哈特里检验的是程序而不是方法：与实验的接近程度取决于方法和基组。"], ["disp", "Дисперсионная энергия на больших расстояниях убывает как −C₆/R⁶; эмпирические поправки D3 и D4 добавляют такие слагаемые к энергии DFT.", "At large distances the dispersion energy falls off as −C₆/R⁶; the empirical corrections D3 and D4 add such terms to the DFT energy.", "在大距离处色散能按 −C₆/R⁶ 衰减；经验校正 D3 和 D4 就是把这类项加到 DFT 能量上。"], ["aim", "Критическая точка связи — седло плотности между ядрами. Знак лапласиана в ней отличает ковалентную связь (отрицательный) от ионной и водородной (положительный).", "A bond critical point is a saddle of the density between the nuclei. The sign of the Laplacian there tells a covalent bond (negative) from ionic and hydrogen bonds (positive).", "键临界点是核之间密度的鞍点。该点拉普拉斯量的符号区分共价键（负）与离子键和氢键（正）。"], ["dft", "Теорема Хоэнберга–Кона: плотность основного состояния однозначно определяет внешний потенциал, а с ним и все свойства системы. Точный функционал существует, но неизвестен.", "The Hohenberg–Kohn theorem: the ground-state density determines the external potential uniquely, and with it every property of the system. The exact functional exists but is unknown.", "霍恩伯格–科恩定理：基态密度唯一地确定外势，从而确定体系的所有性质。精确泛函存在，但形式未知。"], ["huckel", "В методе Хюккеля учитываются только π-электроны: все кулоновские интегралы равны α, резонансные интегралы соседних атомов — β, остальные — нулю.", "The Hückel method treats only the π electrons: all Coulomb integrals equal α, the resonance integrals of neighbouring atoms β, and all others zero.", "休克尔方法只考虑 π 电子：所有库仑积分都等于 α，相邻原子的共振积分等于 β，其余为零。"], ["wh", "Реакция Дильса–Альдера ([4 + 2]) разрешена термически, а [2 + 2]-циклоприсоединение двух алкенов — только фотохимически.", "The Diels–Alder reaction ([4 + 2]) is thermally allowed, while the [2 + 2] cycloaddition of two alkenes is allowed only photochemically.", "狄尔斯–阿尔德反应（[4 + 2]）是热允许的，而两个烯烃的 [2 + 2] 环加成只在光化学条件下允许。"], ["nmr", "Химический сдвиг δ в ppm одинаков на любом приборе, а расщепление J в герцах — тоже; меняется только их соотношение.", "The chemical shift δ in ppm is the same on any spectrometer, and so is the splitting J in hertz; only their ratio changes.", "化学位移 δ（ppm）在任何谱仪上都相同，以赫兹表示的裂分 J 也相同；变化的只是两者之比。"], ["conf", "В бутане при 298 K около двух третей молекул анти, треть — гош: разница энергий всего 3–4 кДж/моль.", "In butane at 298 K about two thirds of the molecules are anti and a third gauche: the energy difference is only 3–4 kJ/mol.", "298 K 时丁烷约三分之二的分子为反式，三分之一为邻位交叉：能量差只有 3–4 kJ/mol。"], ["rel", "Внутренние электроны золота движутся со скоростью больше половины скорости света: их масса растёт на 22 %.", "The inner electrons of gold move at more than half the speed of light: their mass grows by 22 %.", "金的内层电子以超过光速一半的速度运动：其质量增大 22%。"], ["cryst", "У гранецентрированной решётки нет отражений (100) и (110): первая линия меди на дифрактограмме — (111) при 2θ = 43,3°.", "A face-centred lattice has no (100) and (110) reflections: the first line of copper in a powder pattern is (111) at 2θ = 43.3°.", "面心晶格没有 (100) 和 (110) 衍射：铜粉末衍射图的第一条线是 2θ = 43.3° 处的 (111)。"], ["walsh", "При изгибе AH₂ пара πᵤ расщепляется: 2a₁ опускается, а 1b₁, перпендикулярная плоскости молекулы, остаётся на месте.", "On bending AH₂ the πᵤ pair splits: 2a₁ drops, while 1b₁, perpendicular to the molecular plane, stays where it was.", "AH₂ 弯曲时 πᵤ 对分裂：2a₁ 下降，而垂直于分子平面的 1b₁ 保持不变。"], ["post", "Наблюдаемым величинам соответствуют эрмитовы операторы: их собственные значения всегда вещественны, а собственные функции для разных значений ортогональны.", "Observables correspond to Hermitian operators: their eigenvalues are always real, and eigenfunctions belonging to different values are orthogonal.", "可观测量对应厄米算符：其本征值总是实数，属于不同本征值的本征函数相互正交。"], ["ham", "Отталкивание электронов 1/r₁₂ — единственное слагаемое, связывающее электроны между собой. Из-за него уравнение Шрёдингера для нескольких электронов не решается точно.", "The electron repulsion 1/r₁₂ is the only term that couples the electrons to each other. Because of it the Schrödinger equation for several electrons has no exact solution.", "电子排斥 1/r₁₂ 是唯一把电子彼此耦合在一起的项。正因为它，多电子薛定谔方程无法精确求解。"], ["bo", "Приближение Борна–Оппенгеймера нарушается там, где электронные состояния сближаются по энергии, — например, у конических пересечений, через которые идут многие фотохимические реакции.", "The Born–Oppenheimer approximation breaks down where electronic states come close in energy — at conical intersections, for example, through which many photochemical reactions pass.", "在电子态能量相互接近的地方，玻恩–奥本海默近似失效——例如在锥形交叉点，许多光化学反应都经过那里。"], ["au", "Скорость света в атомных единицах равна примерно 137 — обратной постоянной тонкой структуры. Поэтому релятивистские эффекты малы у лёгких атомов и важны у тяжёлых.", "In atomic units the speed of light is about 137 — the inverse of the fine-structure constant. Relativistic effects are therefore small for light atoms and important for heavy ones.", "在原子单位中光速约为 137——即精细结构常数的倒数。因此相对论效应对轻原子很小，对重原子很重要。"], ["pes", "У молекулы из N атомов поверхность потенциальной энергии зависит от 3N − 6 внутренних координат (3N − 5 у линейной): уже у воды это трёхмерная поверхность.", "For a molecule of N atoms the potential energy surface depends on 3N − 6 internal coordinates (3N − 5 if linear): already for water it is a three-dimensional surface.", "由 N 个原子组成的分子，其势能面依赖于 3N − 6 个内坐标（线性分子为 3N − 5 个）：水分子的势能面就已经是三维的。"], ["sym", "Правило альтернативного запрета: у молекул с центром симметрии колебания, активные в ИК-спектре, неактивны в спектре КР, и наоборот.", "The rule of mutual exclusion: in molecules with a centre of symmetry, vibrations active in the IR spectrum are inactive in Raman, and vice versa.", "互斥规则：在有对称中心的分子中，红外活性的振动在拉曼光谱中无活性，反之亦然。"], ["pauli", "Определитель Слейтера антисимметричен сам по себе: перестановка двух электронов — это перестановка двух строк определителя, и знак меняется.", "A Slater determinant is antisymmetric by construction: exchanging two electrons swaps two rows of the determinant, and the sign changes.", "斯莱特行列式本身就是反对称的：交换两个电子就是交换行列式的两行，符号随之改变。"], ["sc", "Энергия одного определителя — сумма одноэлектронных интегралов hᵢᵢ и половина суммы Jᵢⱼ − Kᵢⱼ по парам спин-орбиталей; так и записывается энергия Хартри–Фока.", "The energy of a single determinant is the sum of the one-electron integrals hᵢᵢ plus half the sum of Jᵢⱼ − Kᵢⱼ over pairs of spin orbitals; this is how the Hartree–Fock energy is written.", "单个行列式的能量等于单电子积分 hᵢᵢ 之和，加上对自旋轨道对求和的 Jᵢⱼ − Kᵢⱼ 的一半；哈特里–福克能量正是这样写出的。"], ["scf", "Начальное приближение важно: SCF часто стартует с гамильтониана без отталкивания электронов или с суммы атомных плотностей, и от старта зависит, к какому решению он придёт.", "The starting guess matters: SCF often starts from the Hamiltonian without electron repulsion or from a sum of atomic densities, and the start decides which solution it reaches.", "初始猜测很重要：SCF 常从不含电子排斥的哈密顿量或原子密度之和开始，起点决定它会收敛到哪个解。"], ["basis", "Поляризационные функции (d на тяжёлых атомах, p на водороде) позволяют облаку деформироваться в молекуле; диффузные функции нужны для анионов и слабых взаимодействий.", "Polarization functions (d on heavy atoms, p on hydrogen) let the cloud deform in the molecule; diffuse functions are needed for anions and weak interactions.", "极化函数（重原子上的 d、氢上的 p）使电子云能在分子中变形；描述阴离子和弱相互作用需要弥散函数。"], ["nm", "Гармонические частоты метода Хартри–Фока обычно завышены примерно на 10 %, поэтому их часто умножают на масштабный множитель около 0,9.", "Harmonic Hartree–Fock frequencies are usually about 10 % too high, so they are often multiplied by a scaling factor near 0.9.", "哈特里–福克谐振频率通常偏高约 10%，因此常乘以约 0.9 的校正因子。"], ["mo", "У молекул от B₂ до N₂ σ-орбиталь из 2p лежит выше π-орбиталей из-за смешивания 2s и 2p, а у O₂ и F₂ — ниже. Поэтому B₂ тоже парамагнитна.", "From B₂ to N₂ the σ orbital from 2p lies above the π orbitals because 2s and 2p mix; in O₂ and F₂ it lies below. That is why B₂ is paramagnetic too.", "从 B₂ 到 N₂，由于 2s 与 2p 混合，来自 2p 的 σ 轨道高于 π 轨道；而在 O₂ 和 F₂ 中则低于 π 轨道。因此 B₂ 也是顺磁性的。"], ["terms", "У кислорода (2p⁴) основной терм ³P₂: оболочка заполнена больше чем наполовину, и наименьшую энергию имеет уровень с наибольшим J.", "The ground term of oxygen (2p⁴) is ³P₂: the shell is more than half full, and the level with the largest J has the lowest energy.", "氧原子（2p⁴）的基态光谱项是 ³P₂：壳层超过半满，J 最大的能级能量最低。"], ["hat", "Радиальная функция орбитали с квантовыми числами n и l имеет n − l − 1 узлов: у 2s один сферический узел, у 2p — ни одного.", "The radial function of an orbital with quantum numbers n and l has n − l − 1 nodes: 2s has one spherical node, 2p has none.", "量子数为 n 和 l 的轨道，其径向函数有 n − l − 1 个节点：2s 有一个球形节面，2p 没有。"], ["var", "Поправка первого порядка теории возмущений к энергии — среднее значение возмущения в невозмущённом состоянии, а поправка второго порядка для основного состояния всегда отрицательна.", "The first-order perturbation correction to the energy is the average of the perturbation in the unperturbed state, and the second-order correction to the ground state is always negative.", "一阶微扰能量修正等于微扰在未微扰态中的平均值，而基态的二阶修正总是负的。"], ["cf", "Спектрохимический ряд упорядочивает лиганды по силе поля: I⁻ < Br⁻ < Cl⁻ < F⁻ < H₂O < NH₃ < en < CN⁻ < CO. Сильное поле выгодно низкоспиновому состоянию.", "The spectrochemical series orders ligands by field strength: I⁻ < Br⁻ < Cl⁻ < F⁻ < H₂O < NH₃ < en < CN⁻ < CO. A strong field favours the low-spin state.", "光谱化学序列按场强排列配体：I⁻ < Br⁻ < Cl⁻ < F⁻ < H₂O < NH₃ < en < CN⁻ < CO。强场有利于低自旋态。"], ["h2", "Неограниченный метод (UHF) при растяжении H₂ правильно уходит к двум атомам, но платит за это смешиванием синглета и триплета — спиновым загрязнением.", "The unrestricted method (UHF) goes correctly to two atoms when H₂ is stretched, but pays for it by mixing singlet and triplet — spin contamination.", "拉伸 H₂ 时，非限制性方法（UHF）能正确地趋于两个原子，但代价是单重态与三重态混合——自旋污染。"], ["he", "Функции Хиллерааса явно зависят от расстояния между электронами r₁₂ и уже с несколькими членами дают энергию гелия с точностью до миллихартри.", "Hylleraas functions depend explicitly on the interelectronic distance r₁₂ and give the helium energy to a millihartree with only a few terms.", "Hylleraas 函数显式依赖电子间距离 r₁₂，只需几项就能把氦原子能量算到毫哈特里的精度。"], ["dens", "Вдали от молекулы плотность убывает экспоненциально, как exp(−2√(2I)·r), где I — первый потенциал ионизации в атомных единицах.", "Far from a molecule the density decays exponentially, as exp(−2√(2I)·r), where I is the first ionization potential in atomic units.", "远离分子时密度按指数衰减，形如 exp(−2√(2I)·r)，其中 I 是以原子单位表示的第一电离能。"], ["opt", "Оптимизация останавливается в стационарной точке, но не обязательно в минимуме: только расчёт частот показывает, нет ли мнимых частот.", "An optimization stops at a stationary point, not necessarily at a minimum: only a frequency calculation shows whether there are imaginary frequencies.", "几何优化停在驻点，但不一定是极小点：只有频率计算才能显示是否存在虚频。"], ["thermo", "Низкие частоты (меньше примерно 100 см⁻¹) в гармоническом приближении сильно завышают энтропию; поэтому для них применяют квазигармоническую поправку Гримме (qRRHO).", "Low frequencies (below roughly 100 cm⁻¹) strongly overestimate the entropy in the harmonic approximation, so Grimme's quasi-harmonic correction (qRRHO) is applied to them.", "低频振动（低于约 100 cm⁻¹）在谐振近似下会严重高估熵，因此对它们采用 Grimme 的准谐振校正（qRRHO）。"], ["eqm", "Ошибка расчёта ΔG в 1 ккал/моль (4,2 кДж/моль) при комнатной температуре меняет константу равновесия примерно в 5 раз.", "An error of 1 kcal/mol (4.2 kJ/mol) in a computed ΔG changes the equilibrium constant about fivefold at room temperature.", "在室温下，ΔG 计算误差 1 kcal/mol（4.2 kJ/mol）会使平衡常数改变约 5 倍。"], ["kin", "Реакция первого порядка с периодом полупревращения около часа при комнатной температуре имеет барьер ΔG‡ около 94 кДж/моль (22,5 ккал/моль).", "A first-order reaction with a half-life of about an hour at room temperature has a barrier ΔG‡ of about 94 kJ/mol (22.5 kcal/mol).", "室温下半衰期约一小时的一级反应，其势垒 ΔG‡ 约为 94 kJ/mol（22.5 kcal/mol）。"], ["cicc", "CCSD(T) называют «золотым стандартом» квантовой химии: в хорошем базисе он даёт энергии реакций с точностью около 1 ккал/моль для молекул с одной главной конфигурацией.", "CCSD(T) is called the “gold standard” of quantum chemistry: in a good basis it gives reaction energies to about 1 kcal/mol for molecules dominated by one configuration.", "CCSD(T) 被称为量子化学的“金标准”：在好的基组中，对单一主导组态的分子，其反应能精度约为 1 kcal/mol。"], ["mp2", "MP2 хорошо описывает дисперсионное притяжение, но для стопок π-систем, например в димере бензола, часто его переоценивает.", "MP2 describes dispersion attraction well but often overestimates it for stacked π systems such as the benzene dimer.", "MP2 能较好地描述色散吸引，但对堆积的 π 体系（如苯二聚体）往往高估。"], ["cas", "Активное пространство CAS(n, m) — n электронов на m орбиталях. Число конфигураций растёт так быстро, что больше примерно 18 орбиталей точно уже не решают.", "An active space CAS(n, m) is n electrons in m orbitals. The number of configurations grows so fast that beyond about 18 orbitals it is no longer solved exactly.", "活性空间 CAS(n, m) 表示 m 个轨道中的 n 个电子。组态数增长极快，超过约 18 个轨道就无法再精确求解。"], ["solv", "Диэлектрическая проницаемость воды около 78, гексана — около 1,9: в неполярном растворителе ионы и сильно полярные структуры почти не стабилизируются.", "The permittivity of water is about 78, that of hexane about 1.9: in a nonpolar solvent ions and strongly polar structures are hardly stabilized.", "水的介电常数约为 78，己烷约为 1.9：在非极性溶剂中，离子和强极性结构几乎得不到稳定化。"], ["lad", "Чем выше ступень лестницы Якова, тем точнее функционал в среднем по большим наборам тестов, но для отдельной молекулы более простой функционал может оказаться ближе к эксперименту.", "The higher the rung of Jacob's ladder, the more accurate a functional is on average over large test sets, but for a single molecule a simpler one may come closer to experiment.", "雅各布天梯的级越高，泛函在大型测试集上的平均精度越高；但对单个分子，较简单的泛函可能更接近实验。"], ["cbs", "Энергия корреляции сходится медленно из-за электронного каспа: функция должна иметь излом при r₁₂ → 0, а гауссовы функции его не воспроизводят. Методы F12 вводят r₁₂ явно.", "The correlation energy converges slowly because of the electron cusp: the function must have a kink at r₁₂ → 0, which Gaussians cannot reproduce. F12 methods include r₁₂ explicitly.", "相关能收敛缓慢是由于电子尖点：波函数在 r₁₂ → 0 处应有折点，而高斯函数无法再现它。F12 方法显式引入 r₁₂。"], ["bsse", "Энергия связи димера воды около 5 ккал/моль (21 кДж/моль) — типичная энергия водородной связи.", "The binding energy of the water dimer is about 5 kcal/mol (21 kJ/mol) — a typical hydrogen bond energy.", "水二聚体的结合能约为 5 kcal/mol（21 kJ/mol）——这是典型的氢键能量。"], ["chg", "Заряды ESP (CHELPG, Мерц–Коллман) подбирают так, чтобы они воспроизводили электростатический потенциал вокруг молекулы, поэтому их используют в силовых полях.", "ESP charges (CHELPG, Merz–Kollman) are fitted to reproduce the electrostatic potential around the molecule, which is why force fields use them.", "ESP 电荷（CHELPG、Merz–Kollman）是为再现分子周围静电势而拟合的，因此被力场采用。"], ["exc", "Интенсивность полосы поглощения задаёт сила осциллятора f: у переходов, запрещённых по симметрии или по спину, она близка к нулю.", "The intensity of an absorption band is given by the oscillator strength f: for transitions forbidden by symmetry or spin it is close to zero.", "吸收带的强度由振子强度 f 决定：对称禁阻或自旋禁阻的跃迁，f 接近于零。"], ["val", "Наборы эталонных данных вроде G2/97 и GMTKN55 собирают надёжные энергии сотен реакций, и по ним сравнивают квантово-химические методы.", "Reference sets such as G2/97 and GMTKN55 collect reliable energies of hundreds of reactions and are used to compare quantum-chemical methods.", "G2/97、GMTKN55 等基准数据集收集了数百个反应的可靠能量，用来比较各种量子化学方法。"], ["disp", "Глубина потенциальной ямы He₂ — всего около 0,9 мэВ (примерно 11 K); это одна из самых слабых связей между нейтральными атомами.", "The well depth of He₂ is only about 0.9 meV (roughly 11 K) — one of the weakest bonds between neutral atoms.", "He₂ 的势阱深度只有约 0.9 meV（约 11 K）——这是中性原子之间最弱的结合之一。"], ["aim", "Пути связей по Бейдеру не всегда совпадают с химическими связями из учебника: они бывают и между атомами, которые связанными не считают.", "Bader's bond paths do not always coincide with the chemical bonds of the textbook: they also appear between atoms not regarded as bonded.", "Bader 的键径并不总与教科书中的化学键一致：在通常不认为成键的原子之间也会出现键径。"], ["dft", "В методе Кона–Шэма кинетическая энергия считается по орбиталям невзаимодействующих электронов, а всё неизвестное собрано в обменно-корреляционный функционал.", "In the Kohn–Sham method the kinetic energy is computed from the orbitals of noninteracting electrons, and everything unknown is gathered in the exchange–correlation functional.", "在科恩–沈方法中，动能由无相互作用电子的轨道计算，所有未知部分都归入交换–相关泛函。"], ["huckel", "У линейного полиена из N атомов энергии π-орбиталей равны α + 2β·cos(kπ/(N + 1)), k = 1…N. С ростом цепи щель ВЗМО–НСМО сужается, и поглощение уходит в видимую область.", "For a linear polyene of N atoms the π orbital energies are α + 2β·cos(kπ/(N + 1)), k = 1…N. As the chain grows the HOMO–LUMO gap narrows and the absorption moves into the visible.", "由 N 个原子组成的线性多烯，其 π 轨道能量为 α + 2β·cos(kπ/(N + 1))，k = 1…N。链越长，HOMO–LUMO 能隙越窄，吸收移向可见区。"], ["wh", "Правила Вудворда–Хофмана выводят из сохранения орбитальной симметрии вдоль пути реакции; равносильный подход — ароматичность переходного состояния по Хюккелю и Мёбиусу.", "The Woodward–Hoffmann rules follow from the conservation of orbital symmetry along the reaction path; an equivalent approach is the Hückel–Möbius aromaticity of the transition state.", "伍德沃德–霍夫曼规则源于沿反应路径的轨道对称性守恒；与之等价的方法是过渡态的休克尔–默比乌斯芳香性。"], ["nmr", "Сдвиг считают как разность экранирований: σ(TMS) − σ, причём TMS рассчитывают тем же методом и базисом, что и молекулу.", "A shift is computed as a difference of shieldings, σ(TMS) − σ, with TMS calculated by the same method and basis as the molecule.", "位移按屏蔽之差计算：σ(TMS) − σ，且 TMS 须与分子用相同的方法和基组计算。"], ["conf", "Оптимизация находит ближайший минимум, а не самый низкий: конформеры гибкой молекулы ищут отдельно, например программой CREST.", "An optimisation finds the nearest minimum, not the lowest: the conformers of a flexible molecule are searched separately, for example with CREST.", "优化找到的是最近的极小点而不是最低的：柔性分子的构象需另行搜索，例如用 CREST。"], ["rel", "Базисы def2 для элементов тяжелее криптона идут вместе с псевдопотенциалом: внутренние электроны заменены потенциалом, а релятивизм в нём уже учтён.", "The def2 basis sets for elements heavier than krypton come with a pseudopotential: the inner electrons are replaced by a potential that already includes relativity.", "比氪重的元素的 def2 基组配有赝势：内层电子由已包含相对论效应的势代替。"], ["cryst", "Плотнейшие упаковки шаров — кубическая и гексагональная — заполняют 74 % объёма; решётка алмаза — всего 34 %.", "The closest packings of spheres — cubic and hexagonal — fill 74 % of the volume; the diamond lattice only 34 %.", "球的最紧密堆积——立方和六方——占体积 74%；金刚石晶格只占 34%。"], ["walsh", "Основное состояние метилена CH₂ — триплет с углом 134°; синглет с двумя электронами на 2a₁ изогнут сильнее, до 102°.", "The ground state of methylene CH₂ is a triplet with an angle of 134°; the singlet with two electrons in 2a₁ is bent more, to 102°.", "亚甲基 CH₂ 的基态是键角 134° 的三重态；2a₁ 上有两个电子的单重态弯得更厉害，为 102°。"], ["post", "Измерение переводит систему в собственное состояние измеряемой величины: если сразу повторить измерение, получится то же значение.", "A measurement leaves the system in an eigenstate of the measured quantity: repeat the measurement at once and you get the same value.", "测量使体系处于所测物理量的本征态：立即重复测量，会得到同一个值。"], ["ham", "В молекуле воды 10 электронов и 3 ядра — 39 координат без учёта спина. Точного аналитического решения нет уже для атома гелия.", "A water molecule has 10 electrons and 3 nuclei — 39 coordinates, spin not counted. There is no exact analytic solution already for the helium atom.", "水分子有 10 个电子和 3 个原子核——不计自旋共 39 个坐标。即使是氦原子也没有精确的解析解。"], ["bo", "Приближение Борна–Оппенгеймера нарушается там, где электронные состояния сближаются, — у конических пересечений. На этом стоит фотохимия.", "The Born–Oppenheimer approximation breaks down where electronic states come close — at conical intersections. Photochemistry rests on this.", "在电子态彼此靠近的地方——锥形交叉处——玻恩–奥本海默近似失效。光化学正是建立在这一点上。"], ["au", "Атомная единица времени — около 24 аттосекунд: за это время электрон на боровской орбите атома водорода проходит один радиан.", "The atomic unit of time is about 24 attoseconds: in that time the electron on the Bohr orbit of hydrogen travels one radian.", "原子时间单位约为 24 阿秒：在这段时间里，氢原子玻尔轨道上的电子转过一个弧度。"], ["pes", "У н-бутана три минимума — анти и два гош, у н-гексана их уже около десятка. Поиск глобального минимума — отдельная задача.", "n-Butane has three minima — anti and two gauche; n-hexane already has about ten. Finding the global minimum is a task of its own.", "正丁烷有三个极小值——反式和两个邻位交叉式；正己烷已有十个左右。寻找全局极小值本身就是一项任务。"], ["sym", "Молекула с центром инверсии не может иметь дипольного момента — поэтому у CO₂ и бензола μ = 0.", "A molecule with an inversion centre cannot have a dipole moment — this is why μ = 0 for CO₂ and benzene.", "具有对称中心的分子不可能有偶极矩——因此 CO₂ 和苯的 μ = 0。"], ["pauli", "Принцип Паули объясняет отталкивание закрытых оболочек: два атома гелия не образуют связи, потому что четыре электрона не помещаются на одну связывающую орбиталь.", "The Pauli principle explains closed-shell repulsion: two helium atoms form no bond because four electrons do not fit into one bonding orbital.", "泡利原理解释了闭壳层之间的排斥：两个氦原子不成键，因为四个电子无法都放进一个成键轨道。"], ["sc", "Если поменять местами две строки определителя, он сменит знак. Это и есть антисимметрия волновой функции, записанная одной строчкой алгебры.", "Swap two rows of a determinant and it changes sign. That is the antisymmetry of the wavefunction written as one line of algebra.", "交换行列式的两行，它就变号。这就是用一行代数写出的波函数反对称性。"], ["scf", "Если ССП не сходится, помогают сдвиг уровней, затухание и лучшее начальное приближение — например, орбитали из расчёта в меньшем базисе.", "If the SCF does not converge, level shifting, damping and a better initial guess help — for example orbitals from a calculation in a smaller basis.", "若 SCF 不收敛，能级移动、阻尼和更好的初始猜测会有帮助——例如用小基组计算得到的轨道。"], ["basis", "Звёздочка в 6-31G* означает d-функции на тяжёлых атомах; две звёздочки в 6-31G** — ещё и p-функции на атомах водорода.", "The star in 6-31G* means d functions on heavy atoms; the two stars in 6-31G** add p functions on hydrogens as well.", "6-31G* 中的星号表示重原子上的 d 函数；6-31G** 中的两个星号还在氢原子上加上 p 函数。"], ["nm", "Нелинейная молекула из N атомов имеет 3N − 6 нормальных колебаний, линейная — 3N − 5: у H₂O их три, у CO₂ — четыре.", "A non-linear molecule of N atoms has 3N − 6 normal modes, a linear one 3N − 5: three for H₂O, four for CO₂.", "由 N 个原子组成的非线性分子有 3N − 6 个简正振动，线性分子有 3N − 5 个：H₂O 有三个，CO₂ 有四个。"], ["mo", "У O₂ два неспаренных электрона на разрыхляющих π*-орбиталях, поэтому кислород парамагнитен — одно из первых подтверждений теории МО.", "O₂ has two unpaired electrons in antibonding π* orbitals, so oxygen is paramagnetic — one of the first confirmations of MO theory.", "O₂ 在反键 π* 轨道上有两个未成对电子，所以氧是顺磁性的——这是分子轨道理论最早的证据之一。"], ["terms", "Основной терм атома углерода — ³P: по правилу Хунда два p-электрона занимают разные орбитали с параллельными спинами.", "The ground term of the carbon atom is ³P: by Hund's rule the two p electrons occupy different orbitals with parallel spins.", "碳原子的基态谱项是 ³P：按洪德规则，两个 p 电子以平行自旋占据不同的轨道。"], ["hat", "В атоме водорода энергия зависит только от n, так что 2s и 2p вырождены. В многоэлектронных атомах экранирование снимает это вырождение.", "In the hydrogen atom the energy depends only on n, so 2s and 2p are degenerate. In many-electron atoms screening lifts this degeneracy.", "氢原子的能量只取决于 n，因此 2s 与 2p 简并。在多电子原子中，屏蔽解除了这种简并。"], ["var", "Ошибка вариационной энергии квадратична по ошибке волновой функции: энергия может быть хорошей, а сама функция — заметно хуже.", "The error of a variational energy is quadratic in the error of the wavefunction: the energy can be good while the function itself is noticeably worse.", "变分能量的误差是波函数误差的二次方：能量可能已经很好，而函数本身仍明显较差。"], ["cf", "[Ti(H₂O)₆]³⁺ поглощает около 20 000 см⁻¹ — d–d-переход через щель Δ в зелёно-жёлтой области, поэтому раствор фиолетовый.", "[Ti(H₂O)₆]³⁺ absorbs near 20,000 cm⁻¹ — a d–d transition across the gap Δ in the green–yellow region, so the solution is violet.", "[Ti(H₂O)₆]³⁺ 在约 20 000 cm⁻¹ 处吸收——跨越分裂能 Δ 的 d–d 跃迁位于黄绿区，所以溶液呈紫色。"], ["h2", "Энергия связи H₂ — 4,75 эВ при длине 0,741 Å. Простейшая модель МО ЛКАО из двух 1s-функций даёт около 2,7 эВ: вклад корреляции велик даже здесь.", "The bond energy of H₂ is 4.75 eV at 0.741 Å. The simplest LCAO-MO model with two 1s functions gives about 2.7 eV: correlation matters even here.", "H₂ 的键能为 4.75 eV，键长 0.741 Å。由两个 1s 函数构成的最简单 LCAO-MO 模型只给出约 2.7 eV：即使在这里，关联的贡献也很大。"], ["he", "Энергия ионизации гелия — 24,6 эВ, самая большая среди всех атомов.", "The ionization energy of helium is 24.6 eV, the largest of all atoms.", "氦的电离能为 24.6 eV，是所有原子中最大的。"], ["dens", "Электронную плотность можно измерить: рентгеновская дифракция видит именно ρ(r), а не волновую функцию.", "Electron density can be measured: X-ray diffraction sees ρ(r) itself, not the wavefunction.", "电子密度是可以测量的：X 射线衍射看到的正是 ρ(r)，而不是波函数。"], ["opt", "Оптимизацию проверяют по силам и смещениям, но после неё нужен расчёт частот: только он покажет, минимум это или седловая точка.", "An optimization is checked by forces and displacements, but a frequency calculation must follow: only it tells a minimum from a saddle point.", "几何优化按力和位移判断收敛，但之后必须计算频率：只有频率能区分极小点和鞍点。"], ["thermo", "Гармонические частоты обычно завышены на несколько процентов, поэтому их и энергию нулевых колебаний часто умножают на масштабный множитель.", "Harmonic frequencies are usually a few per cent too high, so they and the zero-point energy are often multiplied by a scaling factor.", "谐振频率通常偏高百分之几，因此频率和零点能常乘以一个标度因子。"], ["eqm", "При 298 K ошибка в ΔG на 5,7 кДж/моль меняет константу равновесия в 10 раз.", "At 298 K an error of 5.7 kJ/mol in ΔG changes the equilibrium constant tenfold.", "在 298 K，ΔG 误差 5.7 kJ/mol 会使平衡常数变化 10 倍。"], ["kin", "Правило «на 10 градусов теплее — вдвое быстрее» соответствует энергии активации около 50 кДж/моль при комнатной температуре.", "The rule “10 degrees warmer — twice as fast” corresponds to an activation energy of about 50 kJ/mol at room temperature.", "“温度升高 10 度，速率加倍”的经验规则对应室温下约 50 kJ/mol 的活化能。"], ["cicc", "Полное КВ точно в данном базисе, но число определителей растёт факториально: у воды в базисе cc-pVDZ их около 2·10⁹.", "Full CI is exact within the basis, but the number of determinants grows factorially: about 2·10⁹ for water in cc-pVDZ.", "完全 CI 在给定基组内是精确的，但行列式数目按阶乘增长：cc-pVDZ 基组中的水约有 2·10⁹ 个。"], ["mp2", "MP2 стоит как N⁵ и неплохо передаёт дисперсию, но переоценивает её для стопок π-систем — например, в димере бензола.", "MP2 scales as N⁵ and captures dispersion fairly well, but overestimates it for stacked π systems — the benzene dimer, for example.", "MP2 的计算量按 N⁵ 增长，能较好地描述色散，但会高估堆叠 π 体系的色散——例如苯二聚体。"], ["cas", "Запись CAS(n,m) означает n электронов на m активных орбиталях. Для разрыва одинарной связи обычно хватает CAS(2,2).", "CAS(n,m) means n electrons in m active orbitals. Breaking a single bond usually needs just CAS(2,2).", "CAS(n,m) 表示 n 个电子分布在 m 个活性轨道上。断裂一个单键通常 CAS(2,2) 就够了。"], ["solv", "Вода с ε ≈ 78 ослабляет притяжение зарядов почти в 80 раз, поэтому соли диссоциируют в воде и почти не диссоциируют в бензоле (ε ≈ 2,3).", "Water with ε ≈ 78 weakens the attraction of charges almost 80-fold, so salts dissociate in water and hardly at all in benzene (ε ≈ 2.3).", "ε ≈ 78 的水把电荷间的吸引减弱近 80 倍，因此盐在水中解离，而在苯（ε ≈ 2.3）中几乎不解离。"], ["lad", "Каждая ступень «лестницы Иакова» добавляет новый ингредиент, но не гарантирует лучшего результата в каждой задаче: функционал выбирают по тестам для своего класса систем.", "Each rung of Jacob's ladder adds an ingredient but does not guarantee a better result for every problem: choose a functional by benchmarks for your class of systems.", "“雅各布天梯”的每一级都增加一种成分，但并不保证每个问题的结果都更好：应根据针对自己体系类别的基准测试来选择泛函。"], ["cbs", "Энергия Хартри–Фока сходится к пределу базиса почти экспоненциально, а корреляционная — медленно, как X⁻³. Поэтому их экстраполируют раздельно.", "The Hartree–Fock energy approaches the basis-set limit almost exponentially, the correlation energy slowly, as X⁻³. So they are extrapolated separately.", "哈特里–福克能量几乎按指数趋于基组极限，而关联能则按 X⁻³ 缓慢收敛。因此两者分别外推。"], ["bsse", "В поправке противовеса Бойса–Бернарди каждый мономер считают в полном базисе димера: функции партнёра стоят на «атомах-призраках» без ядер и электронов.", "In the Boys–Bernardi counterpoise correction each monomer is computed in the full dimer basis: the partner's functions sit on ghost atoms with no nuclei or electrons.", "在 Boys–Bernardi 平衡校正中，每个单体都在二聚体的完整基组中计算：伙伴的函数放在没有核和电子的“鬼原子”上。"], ["chg", "Заряды по ЭСП (CHELPG, Merz–Kollman) подбирают так, чтобы точечные заряды воспроизводили потенциал вокруг молекулы; их используют в силовых полях.", "ESP charges (CHELPG, Merz–Kollman) are fitted so that point charges reproduce the potential around the molecule; force fields use them.", "ESP 电荷（CHELPG、Merz–Kollman）是这样拟合的：让点电荷重现分子周围的电势；力场使用这类电荷。"], ["exc", "Синглетное возбуждение выше триплетного с той же парой орбиталей на удвоенный обменный интеграл 2K.", "A singlet excitation lies above the triplet with the same pair of orbitals by twice the exchange integral, 2K.", "单重态激发比同一对轨道的三重态激发高出两倍交换积分 2K。"], ["val", "Сравнивайте расчёт с экспериментом для одной и той же величины: Dₑ — не D₀, а равновесная длина rₑ — не усреднённая по колебаниям r₀.", "Compare calculation and experiment for the same quantity: Dₑ is not D₀, and the equilibrium length rₑ is not the vibrationally averaged r₀.", "将计算与实验比较时要针对同一个量：Dₑ 不是 D₀，平衡键长 rₑ 也不是振动平均的 r₀。"], ["disp", "Дисперсия убывает как 1/R⁶, но складывается от всех пар атомов, поэтому в больших молекулах и кристаллах даёт десятки кДж/моль.", "Dispersion falls off as 1/R⁶ but adds up over all atom pairs, so in large molecules and crystals it reaches tens of kJ/mol.", "色散按 1/R⁶ 衰减，但对所有原子对求和，因此在大分子和晶体中可达几十 kJ/mol。"], ["aim", "Число критических точек подчиняется соотношению n − b + r − c = 1. У бензола 12 ядер, 12 связей и один цикл: 12 − 12 + 1 = 1.", "The numbers of critical points obey n − b + r − c = 1. Benzene has 12 nuclei, 12 bonds and one ring: 12 − 12 + 1 = 1.", "临界点的数目满足 n − b + r − c = 1。苯有 12 个核、12 个键和一个环：12 − 12 + 1 = 1。"], ["dft", "Теоремы Хоэнберга–Кона доказывают, что точный функционал существует, но не говорят, как он выглядит, — отсюда сотни приближённых функционалов.", "The Hohenberg–Kohn theorems prove that the exact functional exists but say nothing about its form — hence hundreds of approximate functionals.", "霍恩伯格–科恩定理证明了精确泛函存在，却没有给出它的形式——因此有数百种近似泛函。"], ["huckel", "По Хюккелю π-орбитали бензола имеют энергии α + 2β, α + β (дважды), α − β (дважды) и α − 2β: шесть π-электронов занимают три связывающие.", "In Hückel theory the π orbitals of benzene lie at α + 2β, α + β (twice), α − β (twice) and α − 2β: six π electrons fill the three bonding ones.", "按休克尔方法，苯的 π 轨道能量为 α + 2β、α + β（二重）、α − β（二重）和 α − 2β：六个 π 电子占据三个成键轨道。"], ["wh", "При нагревании бутадиен замыкается в циклобутен конротаторно, а при облучении — дисротаторно.", "On heating butadiene closes to cyclobutene in a conrotatory way, under light in a disrotatory way.", "加热时丁二烯以顺旋方式闭环成环丁烯，光照时则以对旋方式闭环。"], ["nmr", "Химический сдвиг отсчитывают от эталона — тетраметилсилана: δ ≈ σ(TMS) − σ(ядро) в миллионных долях.", "Chemical shifts are measured from a reference, tetramethylsilane: δ ≈ σ(TMS) − σ(nucleus) in parts per million.", "化学位移以四甲基硅烷为参比：δ ≈ σ(TMS) − σ(核)，单位为百万分之一。"], ["conf", "Разница энергий 4,2 кДж/моль (1 ккал/моль) при комнатной температуре даёт соотношение конформеров около 5 : 1.", "An energy gap of 4.2 kJ/mol (1 kcal/mol) at room temperature gives a conformer ratio of about 5 : 1.", "室温下 4.2 kJ/mol（1 kcal/mol）的能量差对应约 5 : 1 的构象比例。"], ["rel", "Жёлтый цвет золота — релятивистский эффект: 6s сжимается, 5d расширяется, и поглощение сдвигается из ультрафиолета в синюю область.", "The yellow colour of gold is a relativistic effect: 6s contracts, 5d expands, and the absorption shifts from the ultraviolet into the blue.", "金的黄色是相对论效应：6s 收缩、5d 扩张，使吸收从紫外移到蓝光区。"], ["cryst", "Рентгеновские лучи рассеиваются на электронах, поэтому атомы водорода в кристалле видны плохо; их положения уточняют нейтронографией.", "X-rays scatter on electrons, so hydrogen atoms in a crystal are hard to see; their positions are refined by neutron diffraction.", "X 射线被电子散射，所以晶体中的氢原子很难看清；它们的位置用中子衍射来精修。"], ["walsh", "H₂O изогнута, а BeH₂ линейна: у воды заполнена орбиталь 3a₁, которая стабилизируется при изгибе, а у BeH₂ она пуста.", "H₂O is bent while BeH₂ is linear: water fills the 3a₁ orbital that is stabilized by bending, while in BeH₂ it is empty.", "H₂O 是弯曲的而 BeH₂ 是线性的：水占据了弯曲时被稳定的 3a₁ 轨道，而在 BeH₂ 中它是空的。"]];
const UI={ru:{t:'Псс, а ты знаешь?',next:'Ещё факт',hide:'Скрыть',open:'Открыть тему'},
  en:{t:'Psst, did you know?',next:'Another fact',hide:'Hide',open:'Open the topic'},
  zh:{t:'嘘，你知道吗？',next:'再来一条',hide:'隐藏',open:'打开主题'}};
/* the tip shows at every start of the program on the Atlas home page; «Скрыть» hides it until the program
   is started again (sessionStorage lives as long as this view of the Atlas). Each start begins with another tip. */
const KEY='qc-atlas-tip-hidden',START='qc-atlas-tip-start';
const today=()=>{const d=new Date();return Math.floor(Date.UTC(d.getFullYear(),d.getMonth(),d.getDate())/864e5)+719163};
let shift=0,box=null,shown=false;
let first=(()=>{try{let v=sessionStorage.getItem(START);if(v===null){v=String(Math.floor(Math.random()*1e6));sessionStorage.setItem(START,v)}return +v}catch(e){return today()}})();
function hidden(){try{return sessionStorage.getItem(KEY)==='1'}catch(e){return false}}
function build(){box=document.createElement('aside');box.className='qtip';box.setAttribute('aria-live','polite');
  box.innerHTML='<img class="qtipQ" alt="" aria-hidden="true" src="assets/img/quill-peek-static-20261026b.webp"><img class="qtipQ qtipW" alt="" aria-hidden="true" src="assets/img/quill-peek-wing-20261026b.webp"><div class="qtipC"><div class="qtipH"></div><p class="qtipT"></p><div class="qtipB"><button type="button" class="btn qtipO"></button><button type="button" class="btn qtipN"></button><button type="button" class="btn qtipX"></button></div></div>';
  /* Quill comes out at a new place each time — on the right or on the left (mirrored), lower or
     higher */
  if(Math.random()<.5)box.classList.add('qtipL');box.dataset.rise=String(Math.random());
  document.body.appendChild(box);
  box.querySelector('.qtipN').onclick=()=>{shift++;fill()};
  box.querySelector('.qtipX').onclick=()=>{try{sessionStorage.setItem(KEY,'1')}catch(e){}box.dataset.gone='1';show(false)};
  box.querySelector('.qtipO').onclick=()=>{const t=cur();if(t&&window.qcOpenPage)window.qcOpenPage(t[0])}}
function cur(){return TIPS.length?TIPS[(first+shift)%TIPS.length]:null}
function fill(){const L=UI[window.qcLang&&window.qcLang()]?window.qcLang():'ru',u=UI[L],t=cur();if(!t)return;
  const k={ru:1,en:2,zh:3}[L];box.querySelector('.qtipH').textContent=u.t;box.querySelector('.qtipT').textContent=t[k];
  box.querySelector('.qtipN').textContent=u.next;box.querySelector('.qtipX').textContent=u.hide;box.querySelector('.qtipO').textContent=u.open+' →';if(shown)requestAnimationFrame(qcTipPad)}
function show(on){if(!box){if(!on)return;build()}
  on=on&&TIPS.length>0&&!box.dataset.gone&&!hidden();if(on)fill();
  if(on&&!shown){const c=box.querySelector('.qtipC'),room=Math.max(0,innerHeight-(c?c.getBoundingClientRect().height:200)-120);box.style.bottom=Math.round(18+room*.4*(+box.dataset.rise||0))+'px'}
  if(on!==shown){shown=on;box.classList.toggle('on',on);document.documentElement.classList.toggle('tipOn',on);if(on)requestAnimationFrame(qcTipPad)}}
/* Atlas the room under the overview is only
   what lets its last row come out from under the tip card — the card's height and its gap, less the footer, which
   lies under the card anyway (was 230 px whatever the card) */
function qcTipPad(){const c=box&&box.querySelector('.qtipC'),f=document.querySelector('.hwrap .qfoot');if(!c)return;
  const need=c.getBoundingClientRect().height+18+12,foot=f?f.getBoundingClientRect().height:0;
  document.documentElement.style.setProperty('--tipPad',Math.max(24,Math.round(need-foot))+'px')}
addEventListener('resize',()=>{if(shown)qcTipPad()});
window.qcTip=show;window.qcTipLang=()=>{if(box&&shown)fill()};
})();
